import { TooltipProvider } from '@/components/ui/tooltip';
import { ArrowDownRight, ArrowRight, ArrowUpRight, Bell, Check, ChevronDown, CircleHelp, Clock3, Compass, HeartHandshake, Leaf, LogOut, MapPin, Menu, PackageCheck, Plus, Route, ShieldCheck, Sparkles, Truck, Users, Utensils, X } from 'lucide-react';
import { Link, Route as WRoute, Switch, useLocation, Router as WouterRouter } from 'wouter';
import { useAnalyzeDonation, useAnalyzeFeedback, useFindMatchingOrganizations, useGenerateWasteInsights, useHealthCheck } from '@workspace/api-client-react';
