type Role = 'DONOR' | 'NGO' | 'VOLUNTEER' | 'ADMIN';
type DonationStatus = 'AVAILABLE' | 'CLAIMED' | 'PICKUP_ASSIGNED' | 'PICKED_UP' | 'DELIVERED' | 'COMPLETED' | 'EXPIRED' | 'CANCELLED';
type Donation = { id: string; food_name: string; food_category: string; quantity: number; quantity_unit: string; pickup_address: string; prepared_at: string; expiry_at: string; status: DonationStatus; description: string };
type Profile = { full_name: string; email: string; role: Role; organization_name: string };
const queryClient = new QueryClient();
const rolePaths: Record<Role, string> = { DONOR: '/donor/dashboard', NGO: '/ngo/dashboard', VOLUNTEER: '/volunteer/dashboard', ADMIN: '/admin/dashboard' };
const roleNames: Record<Role, string> = { DONOR: 'Food donor', NGO: 'Community organization', VOLUNTEER: 'Volunteer courier', ADMIN: 'Network administrator' };
const defaultProfile: Profile = { full_name: 'Maya Chen', email: 'maya@riverbend.org', role: 'DONOR', organization_name: 'Riverbend Kitchen' };
const demoDonations: Donation[] = [
  { id: 'FB-2841', food_name: 'Roasted vegetable bowls', food_category: 'Prepared meals', quantity: 32, quantity_unit: 'meals', pickup_address: '44 Orchard Street', prepared_at: new Date(Date.now() - 3_600_000).toISOString(), expiry_at: new Date(Date.now() + 5 * 3_600_000).toISOString(), status: 'PICKUP_ASSIGNED', description: 'Freshly prepared lunch portions, chilled.' },
  { id: 'FB-2838', food_name: 'Seasonal produce boxes', food_category: 'Produce', quantity: 18, quantity_unit: 'boxes', pickup_address: '12 Mercer Avenue', prepared_at: new Date(Date.now() - 2 * 3_600_000).toISOString(), expiry_at: new Date(Date.now() + 8 * 3_600_000).toISOString(), status: 'AVAILABLE', description: 'Apples, greens, carrots and squash.' },
  { id: 'FB-2826', food_name: 'Sourdough loaves', food_category: 'Bakery', quantity: 24, quantity_unit: 'loaves', pickup_address: '108 Willow Lane', prepared_at: new Date(Date.now() - 18 * 3_600_000).toISOString(), expiry_at: new Date(Date.now() + 18 * 3_600_000).toISOString(), status: 'DELIVERED', description: 'Unsliced artisan loaves from today.' },
];
function readStore<T>(key: string, fallback: T): T {
  try { const value = localStorage.getItem(`foodbridge:${key}`); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; }
}
function saveStore<T>(key: string, value: T) { localStorage.setItem(`foodbridge:${key}`, JSON.stringify(value)); }
function timeGreeting() { const h = new Date().getHours(); return h < 12 ? 'Good morning' : h < 17 ? 'Good afternoon' : 'Good evening'; }
function IconMark() { return <span className="brand-mark"><svg width="27" height="27" viewBox="0 0 30 30" fill="none" aria-hidden="true"><path d="M6 18.8c0-5.7 4-10.8 9-10.8s9 5.1 9 10.8c0 3.4-2 5.2-9 5.2s-9-1.8-9-5.2Z" fill="url(#b)"/><path d="M15 8c-.4-3.1 1.4-5.2 4.7-5.8-.1 3.4-1.4 5.2-4.7 5.8Z" fill="#73ddb4"/><path d="M9.2 17.8c2.4 2 8.2 2.3 11.6.1" stroke="#D7FFE8" strokeOpacity=".65" strokeWidth="1.5" strokeLinecap="round"/><defs><linearGradient id="b" x1="5.8" y1="6.7" x2="26" y2="25" gradientUnits="userSpaceOnUse"><stop stopColor="#A59BFF"/><stop offset="1" stopColor="#5C58D7"/></linearGradient></defs></svg></span>; }
function Brand({ light = false }: { light?: boolean }) { return <Link href="/" className={`brand ${light ? 'brand-light' : ''}`} data-testid="link-brand"><IconMark /><span>food<span className="brand-bridge">bridge</span><i>NETWORK</i></span></Link>; }
function Btn({ children, onClick, href, variant = 'primary', testid, type = 'button', disabled = false }: { children: ReactNode; onClick?: () => void; href?: string; variant?: string; testid: string; type?: 'button' | 'submit'; disabled?: boolean }) {
  const cls = `btn btn-${variant}`;
  if (href) return <Link href={href} className={cls} data-testid={testid}>{children}</Link>;
  return <button type={type} className={cls} onClick={onClick} disabled={disabled} data-testid={testid}>{children}</button>;
}
function StatusPill({ status }: { status: DonationStatus }) { return <span className={`pill pill-${status.toLowerCase()}`} data-testid={`status-donation-${status.toLowerCase()}`}><i />{status.replaceAll('_', ' ')}</span>; }
function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><Router /></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}
function Router() {
  const [location] = useLocation();
  return <RoutedErrorBoundary><Switch>
    <WRoute path="/" component={LandingPage} />
    <WRoute path="/login" component={AuthPage} /><WRoute path="/signup" component={AuthPage} /><WRoute path="/forgot-password" component={AuthPage} />
    <WRoute path="/donor/dashboard" component={WorkspacePage} /><WRoute path="/donor/donate" component={WorkspacePage} /><WRoute path="/donor/donations" component={WorkspacePage} />
    <WRoute path="/ngo/dashboard" component={WorkspacePage} /><WRoute path="/ngo/map" component={WorkspacePage} />
    <WRoute path="/volunteer/dashboard" component={WorkspacePage} />
    <WRoute path="/admin/dashboard" component={WorkspacePage} /><WRoute path="/admin/analytics" component={WorkspacePage} /><WRoute path="/admin/ai-insights" component={WorkspacePage} />
    <WRoute path="/feedback" component={FeedbackPage} /><WRoute path="/impact" component={ImpactPage} />
    <WRoute component={NotFound} />
  </Switch></RoutedErrorBoundary>;
}
function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }
