function VolunteerDashboard({ donations, onUpdate }: {donations:Donation[];onUpdate:(d:Donation[])=>void}) {
 const task=donations.find(d=>d.status==='PICKUP_ASSIGNED'||d.status==='CLAIMED')||donations[0]; const next=task?.status==='PICKUP_ASSIGNED'?'PICKED_UP':'DELIVERED';
 return <div className="volunteer-content"><div className="route-hero glass"><div className="route-hero-copy"><span className="eyebrow"><span className="live-dot"/> ROUTE STATUS · READY</span><h2>Your time makes<br/>the difference.</h2><p>One pickup. One delivery. A direct line between extra food and someone who can use it.</p><div className="route-statline"><span><b>2.4 mi</b><small>round trip</small></span><i/><span><b>28 meals</b><small>in this handoff</small></span><i/><span><b>18 min</b><small>estimated</small></span></div></div><div className="route-mini-map map-grid"><span className="mini-route-line"/><span className="mini-route-pin pin-a"><Utensils size={13}/></span><span className="mini-route-pin pin-b"><HeartHandshake size={13}/></span><span className="mini-route-courier"><Truck size={12}/></span><small>RIVER DISTRICT</small></div></div><div className="route-progress panel glass"><div className="panel-heading"><div><span className="eyebrow">YOUR NEXT HANDOFF</span><h3>{task?.food_name||'No pickup assigned yet'}</h3></div>{task&&<StatusPill status={task.status}/>}</div>{task?<><div className="route-steps"><div className="route-step done"><span><Check size={13}/></span><div><b>Route accepted</b><small>Today · 2:28 PM</small></div></div><div className={`route-step ${task.status==='PICKUP_ASSIGNED'?'current':'done'}`}><span>{task.status==='PICKUP_ASSIGNED'?'2':<Check size={13}/>}</span><div><b>Pick up from {task.pickup_address}</b><small>32 meal portions · chilled</small></div></div><div className="route-step"><span>3</span><div><b>Deliver to Harbor Community Pantry</b><small>412 River Street · loading entrance</small></div></div></div><div className="route-footer"><span><ShieldCheck size={14}/>Recipient details shared after pickup confirmation.</span><button className="btn btn-primary" onClick={()=>onUpdate(donations.map(d=>d.id===task.id?{...d,status:next as DonationStatus}:d))} data-testid="button-advance-pickup">{task.status==='PICKUP_ASSIGNED'?'Confirm pickup':'Confirm delivery'} <ArrowRight size={15}/></button></div></>:<EmptyState title="No route assigned right now" detail="New pickup opportunities will appear here when they’re ready."/>}</div><div className="volunteer-tip"><span className="tip-icon"><Leaf size={17}/></span><p><b>Small detail, big difference.</b> Keep chilled food cool through the trip. If timing changes, reach out to the donor before the pickup window closes.</p></div></div>;
}
function AnalyticsView({ donations }: {donations:Donation[]}) {
 return <div className="analytics-content"><section className="stat-grid"><StatCard label="Meals redirected" value="18,642" change="+8.3%" icon={Utensils} tone="purple" foot="demo estimate"/><StatCard label="Successful handoffs" value="94.2%" change="+2.1%" icon={PackageCheck} tone="green" foot="illustrative sample"/><StatCard label="Active partners" value="42" icon={HeartHandshake} tone="blue" foot="sample accounts"/><StatCard label="Food rescued" value="3.8 t" change="+6.7%" icon={Leaf} tone="gold" foot="not real-world impact"/></section><section className="content-grid"><div className="panel glass rhythm-panel analytics-chart"><div className="panel-heading"><div><span className="eyebrow">DEMO NETWORK · 30 DAYS</span><h3>Rescued meals over time</h3></div><button className="period-button" data-testid="button-analytics-period">Last 30 days <ChevronDown size={13}/></button></div><div className="chart-summary"><b>18,642 <small>meals</small></b><span><ArrowUpRight size={14}/> 8.3% <small>sample trend</small></span></div><MiniChart/><div className="chart-days"><span>JUN 01</span><span>JUN 06</span><span>JUN 11</span><span>JUN 16</span><span>JUN 21</span><span>JUN 26</span><span>JUN 30</span></div><div className="chart-legend"><i/> Meals redirected <small>Illustrative data</small></div></div><div className="panel glass category-panel"><div className="panel-heading"><div><span className="eyebrow">WHAT MOVES</span><h3>By food category</h3></div></div>{[['Prepared meals','68%','purple'],['Produce','51%','green'],['Bakery','38%','blue'],['Pantry staples','26%','gold']].map(([n,v,c])=><div className="category-line" key={n}><div><span>{n}</span><b>{v}</b></div><i className={`progress-track ${c}`}><span style={{width:v}}/></i></div>)}</div></section><div className="panel glass analytics-recent"><div className="panel-heading"><div><span className="eyebrow">LATEST SAMPLE RECORDS</span><h3>Recent donations</h3></div><span className="count-chip">{donations.length} entries</span></div><DonationsCompact donations={donations}/></div></div>;
}
function DonationsCompact({donations}:{donations:Donation[]}) { return <div className="compact-list">{donations.slice(0,3).map(d=><div className="compact-row" key={d.id} data-testid={`compact-donation-${d.id}`}><span className="food-avatar"><Utensils size={15}/></span><b>{d.food_name}</b><span>{d.quantity} {d.quantity_unit}</span><StatusPill status={d.status}/></div>)}</div>; }
function InsightsView({ donations }: {donations:Donation[]}) {
 const generate=useGenerateWasteInsights();
 const [error,setError]=useState(''); const [report,setReport]=useState<Awaited<ReturnType<typeof generate.mutateAsync>>|null>(null);
 const run=async()=>{setError('');const payload:WasteInsightInput={period:'last 30 days',totalDonations:donations.length,mealsRescued:2486,foodSavedKg:380,wasteEntries:donations.map(d=>({foodName:d.food_name,quantity:d.quantity,reason:d.description||'Surplus food shared through the demo',createdAt:d.prepared_at}))};try{setReport(await generate.mutateAsync({data:payload}));}catch{setError('The live insights service is unavailable. Local example observations are shown instead.');}};
 return <div className="insights-layout"><section className="insight-hero glass"><div className="insight-orb"><Sparkles size={25}/></div><div><span className="eyebrow">NETWORK LEARNING · DEMO DATA</span><h2>Better patterns.<br/><span className="gradient-text">More meals saved.</span></h2><p>Use the live insights service to find useful patterns in aggregated rescue activity. These sample observations are illustrative only.</p><button className="btn btn-primary" onClick={run} disabled={generate.isPending} data-testid="button-generate-insights">{generate.isPending?'Reading demo activity…':'Generate live insights'} <Sparkles size={15}/></button></div><div className="insight-data-stamp"><small>INPUT PERIOD</small><b>LAST 30 DAYS</b><small>DEMO AGGREGATE</small></div></section>{error&&<div className="form-error" role="alert" data-testid="status-insights-error">{error}</div>}<div className="insights-cards">{report?.available&&report.insights.length?report.insights.map((item,i)=><article className="insight-card glass" key={`${item.title}-${i}`} data-testid={`card-insight-${i}`}><span className={`insight-index index-${i}`}>0{i+1}</span><span className="insight-category">{item.category} · {item.confidence} CONFIDENCE</span><h3>{item.title}</h3><p>{item.detail}</p><ArrowUpRight size={16}/></article>):[['Fresh food moves fastest','Shorter pickup windows tend to create smoother handoffs for prepared meals.','TIMING'],['Weekday lunch has room to grow','Donations shared before noon can reach local partners while they are still planning.','OPPORTUNITY'],['The bakery connection is strong','A consistent pickup routine can help nearby partners plan for recurring surplus.','ROUTINE']].map(([title,detail,category],i)=><article className="insight-card glass" key={title} data-testid={`card-insight-${i}`}><span className={`insight-index index-${i}`}>0{i+1}</span><span className="insight-category">{report?.available?'SAMPLE OBSERVATION':category}</span><h3>{title}</h3><p>{detail}</p><ArrowUpRight size={16}/></article>)}</div><p className="insight-disclaimer"><ShieldCheck size={15}/> AI outputs are guidance, not food-safety advice. Demo insights are not based on actual community activity.</p></div>;
}
function FeedbackPage() {
 const analyze=useAnalyzeFeedback(); const [rating,setRating]=useState(0); const [category,setCategory]=useState('Experience'); const [message,setMessage]=useState(''); const [sent,setSent]=useState(false); const [result,setResult]=useState<Awaited<ReturnType<typeof analyze.mutateAsync>>|null>(null); const [error,setError]=useState('');
 const submit=async(e:FormEvent)=>{e.preventDefault();setError('');if(!rating||message.trim().length<4){setError('Choose a rating and share a little more detail.');return;}const input:FeedbackAnalysisInput={rating,category,message};try{const response=await analyze.mutateAsync({data:input});setResult(response);}catch{setError('Live feedback analysis is unavailable. Your feedback will be saved locally in demo mode.');}const logs=readStore<Array<{rating:number;category:string;message:string}>>('feedback',[]);saveStore('feedback',[{rating,category,message},...logs]);setSent(true);};
 return <main className="fb-bg noise standalone-page"><header className="standalone-nav"><Brand/><Link href="/" className="text-link" data-testid="link-feedback-home">Back to home <ArrowRight size={14}/></Link></header><div className="feedback-layout"><div className="feedback-story"><span className="eyebrow">A NOTE TO THE NETWORK</span><h1>Good systems<br/>listen <span className="gradient-text">closely.</span></h1><p>Your experience helps us make each handoff clearer, kinder, and easier to trust. This form works locally in demo mode; live feedback service connection is optional.</p><div className="feedback-stat"><span className="feedback-quote">“</span><p>It’s the little things — a clear pickup time, a name I recognize — that make this feel like a neighborhood.</p><small>DEMO MEMBER · COMMUNITY PARTNER</small></div><Link href="/impact" className="text-link" data-testid="link-feedback-impact">See why the network matters <ArrowRight size={14}/></Link></div><div className="feedback-card glass">{sent?<div className="feedback-success" role="status" data-testid="status-feedback-success"><span className="success-ring"><Check size={23}/></span><span className="eyebrow">MESSAGE RECEIVED</span><h2>Thanks for helping<br/>us get better.</h2><p>Your note is saved in this browser’s demo data. {result?`Live analysis: ${result.sentiment.toLowerCase()} — ${result.summary}`:'Live analysis is not connected; no server feedback was sent.'}</p><button className="btn btn-outline" onClick={()=>{setSent(false);setMessage('');setRating(0);setResult(null);}} data-testid="button-send-another">Send another note</button></div>:<form onSubmit={submit}><span className="eyebrow">FEEDBACK FORM</span><h2>How’s it going?</h2><p>Tell us about your FoodBridge experience.</p><fieldset className="rating-field"><legend>Your overall experience</legend><div className="rating-options">{[1,2,3,4,5].map(n=><button type="button" className={rating===n?'rating-selected':''} onClick={()=>setRating(n)} key={n} aria-label={`${n} out of 5`} data-testid={`button-rating-${n}`}>{n}</button>)}</div><div className="rating-labels"><span>Could be better</span><span>Really good</span></div></fieldset><label>What’s this about?<select value={category} onChange={e=>setCategory(e.target.value)} data-testid="select-feedback-category">{['Experience','Donation flow','Pickup and delivery','Community partner','Technical issue','Other'].map(x=><option key={x}>{x}</option>)}</select></label><label>Your note<textarea rows={5} value={message} onChange={e=>setMessage(e.target.value)} placeholder="What went well? What would you change?" required minLength={4} data-testid="input-feedback-message"/></label>{error&&<div className="form-error" role="alert" data-testid="status-feedback-error">{error}</div>}<button type="submit" className="btn btn-primary feedback-submit" disabled={analyze.isPending} data-testid="button-submit-feedback">{analyze.isPending?'Sending note…':'Send feedback'} <ArrowRight size={15}/></button><small className="privacy-note">Your feedback stays private to the FoodBridge team.</small></form>}</div></div><Footer/></main>;
}
function ImpactPage() {
 const values=useMemo(()=>[{n:'18,642',label:'Meals redirected',note:'an illustrative demo total',icon:Utensils,c:'purple'},{n:'3.8 t',label:'Food kept in use',note:'estimated sample volume',icon:Leaf,c:'green'},{n:'42',label:'Community partners',note:'fictional demo accounts',icon:HeartHandshake,c:'blue'}],[]);
 return <main className="fb-bg noise standalone-page impact-page"><header className="standalone-nav"><Brand/><div><Link href="/login" className="nav-login" data-testid="link-impact-login">Log in</Link><Btn href="/signup" testid="button-impact-join">Join the network <ArrowRight size={15}/></Btn></div></header><section className="impact-hero"><div className="impact-copy"><span className="eyebrow"><span className="live-dot"/> THE MEASURE OF A GOOD HANDOFF</span><h1>Impact is<br/>what <span className="gradient-text">we carry</span><br/>together.</h1><p>Food rescue is not just about what stays out of a bin. It is the trust built between the kitchen, the community, and the people willing to make the trip.</p><Link href="/signup" className="text-link" data-testid="link-impact-start">Find your place in the network <ArrowRight size={15}/></Link></div><div className="impact-illustration"><div className="impact-ring ring-a"/><div className="impact-ring ring-b"/><span className="impact-sun"/><div className="impact-bowl"><div/><div/><div/></div><span className="impact-star star-a">✳</span><span className="impact-star star-b">✦</span><span className="impact-stem stem-a"/><span className="impact-stem stem-b"/></div></section><section className="impact-stats"><div className="impact-stat-intro"><span className="eyebrow">THE DEMO NETWORK AT A GLANCE</span><h2>A picture of<br/>what could be.</h2><p>These values are intentionally illustrative. They demonstrate how FoodBridge can surface activity once a live data connection is configured.</p><span className="impact-caveat"><ShieldCheck size={15}/> Not real-world impact</span></div><div className="impact-values">{values.map(({n,label,note,icon:Icon,c},i)=><article className="impact-value glass" key={label} data-testid={`card-impact-${i}`}><span className={`impact-stat-icon ${c}`}><Icon size={18}/></span><strong>{n}</strong><b>{label}</b><small>{note}</small><span className="value-underline"/></article>)}</div></section><section className="impact-story"><div className="story-mark">“</div><div><span className="eyebrow">BEHIND EVERY NUMBER</span><h2>Logistics, with<br/>a human pulse.</h2><p>Surplus food has a short window. A donor needs a fast way to share it; an organization needs enough context to say yes; a volunteer needs a route that fits into their day. The network connects those moments — and makes room for the care that is already there.</p><div className="story-signoff"><span className="status-dot"/>Built for neighborhood-scale rescue <span>·</span> Designed to make every handoff count</div></div></section><section className="impact-cta"><span className="eyebrow">THE NEXT HANDOFF STARTS WITH YOU</span><h2>Make a little room<br/>for <span className="gradient-text">more good.</span></h2><div><Btn href="/signup" testid="button-impact-cta">Find your role <ArrowRight size={15}/></Btn><Btn href="/feedback" variant="quiet" testid="button-impact-feedback">Share a thought <ArrowRight size={15}/></Btn></div></section><Footer/></main>;
}
export default App;
